INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','present-perfect-continuous','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"present-perfect-continuous","title":"Present perfect simple and continuous","level":"B2","order":31,"summary":"The perfect continuous connects an activity with now and draws attention to duration, repetition or visible evidence of recent effort. The activity may still continue or may have just stopped. The perfect simple often highlights a completed result or a number of finished items.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Focus on the activity","Keep both auxiliaries","Questions and negatives","State verbs and completed quantities"],"rules":[{"title":"Focus on the activity","explanation":"The perfect continuous connects an activity with now and draws attention to duration, repetition or visible evidence of recent effort. The activity may still continue or may have just stopped. The perfect simple often highlights a completed result or a number of finished items.","pattern":"Subject + **have been + -ing**","commonMistakes":["A continuous form does not guarantee that the activity is unfinished; context can show that it recently stopped."],"examples":["Use the present perfect continuous: She **has been preparing** the visitor guide for an hour so far today.","Use the present perfect continuous: She **has been restoring** the old portrait for an hour so far today."],"skill":"form"},{"title":"Keep both auxiliaries","explanation":"The construction has three verb parts: **have or has**, then **been**, then an **-ing** form. Only the first auxiliary changes with tense and subject. Been is the past participle of be; it connects perfect aspect with the continuous construction.","pattern":"She **has been working**.","commonMistakes":["Do not omit been or change it to being in this construction."],"examples":["Make a present-perfect-continuous negative: We **have not been preparing** the visitor guide all morning so far today.","Make a present-perfect-continuous negative: We **have not been restoring** the old portrait all morning so far today."],"skill":"meaning"},{"title":"Questions and negatives","explanation":"Move only **have or has** before the subject in questions. Put not after that same auxiliary in negatives. Been and the -ing form remain in place. A short answer repeats only the first auxiliary.","pattern":"Have they **been working**?","commonMistakes":["Have been they working? puts too much of the verb phrase before the subject."],"examples":["Complete the present-perfect-continuous question: Have they **been preparing** the visitor guide for long so far today?","Complete the present-perfect-continuous question: Have they **been restoring** the old portrait for long so far today?"],"skill":"contrast"},{"title":"State verbs and completed quantities","explanation":"Know, own and believe usually describe states and favour perfect simple: I have known her for years. A completed count also favours the simple: I have written three reports. Repeated activity can use continuous: I have been writing reports all morning. The meaning of the verb matters, not just a time expression.","pattern":"I have **known** her for years. / I have **been waiting** for an hour.","commonMistakes":["For and since can accompany simple perfect states; they do not automatically require continuous."],"examples":["Choose the present perfect SIMPLE, focusing on completion: I **have prepared** the visitor guide so far today.","Choose the present perfect SIMPLE, focusing on completion: I **have restored** the old portrait so far today."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"63cc1802-69e7-5d2c-a105-61e98500e6d3","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Use the present perfect continuous: She ____ the visitor guide for an hour so far today.","choices":[{"id":"A","text":"has being preparing"},{"id":"B","text":"has been prepared"},{"id":"C","text":"has been preparing"},{"id":"D","text":"has preparing"}],"answerId":"C","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **has + been + preparing**. The sentence focuses on the duration of the activity so far today.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"present-perfect-continuous-1","fingerprint":"005b0203e081a24ffab068b31d12739c1969754b8a92b756e973103d2b85e2cb","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **has + been + preparing**. The sentence focuses on the duration of the activity so far today.","Choose **has been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect auxiliary requires been, not being.","B":"A past participle here would suggest passive voice rather than the requested active continuous.","C":"Build **has + been + preparing**. The sentence focuses on the duration of the activity so far today.","D":"Been is missing between the perfect auxiliary and the -ing form."}}},{"id":"9341a7a4-a253-513b-abc4-cb18c6974e0c","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Make a present-perfect-continuous negative: We ____ the visitor guide all morning so far today.","choices":[{"id":"A","text":"did not been preparing"},{"id":"B","text":"have not been preparing"},{"id":"C","text":"have been not preparing"},{"id":"D","text":"have not preparing"}],"answerId":"B","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **have**, before **been preparing**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"present-perfect-continuous-1","fingerprint":"8852c96ea72fa660fb8afb21e0be72c5696398dd509ddb9e1da94ade92e319ee","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **have**, before **been preparing**.","Choose **have not been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did cannot combine with been to make a perfect continuous negative.","B":"Put not after **have**, before **been preparing**.","C":"The ordinary negative position is after the first auxiliary, before been.","D":"Been is missing."}}},{"id":"bc0d0742-86a9-54fd-ac4c-ccc860c01b8c","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Complete the present-perfect-continuous question: Have they ____ the visitor guide for long so far today?","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"been preparing"},{"id":"C","text":"being preparing"},{"id":"D","text":"been prepare"}],"answerId":"B","hint":"The first auxiliary has already moved. Supply **been + -ing** after the subject.","explanation":"The first auxiliary is already at the front. After they, keep **been + preparing**.","keywords":["continuous-question"],"skill":"continuous-question","contextKey":"present-perfect-continuous-1","fingerprint":"806c30000e9d8dbcafca9281ba3814444c2fdc7361c04652de5c8560d520f2c9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary has already moved. Supply **been + -ing** after the subject.","The first auxiliary is already at the front. After they, keep **been + preparing**.","Choose **been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The linking auxiliary been is missing.","B":"The first auxiliary is already at the front. After they, keep **been + preparing**.","C":"The perfect auxiliary requires been, not being.","D":"The active continuous part requires -ing, not the base form."}}},{"id":"5ce54c58-eb15-58de-a042-f3c0cbd933e8","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Choose the present perfect SIMPLE, focusing on completion: I ____ the visitor guide so far today.","choices":[{"id":"A","text":"have been preparing"},{"id":"B","text":"have preparing"},{"id":"C","text":"have to prepare"},{"id":"D","text":"have prepared"}],"answerId":"D","hint":"Separate **completion** from **duration**. The requested form is perfect simple.","explanation":"The instruction focuses on a completed result, so use the simple perfect **have prepared**.","keywords":["simple-continuous-contrast"],"skill":"simple-continuous-contrast","contextKey":"present-perfect-continuous-1","fingerprint":"88de5d02005fbb18386c8d77409fa2076567b91c1fcded05d310eb211833fca8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **completion** from **duration**. The requested form is perfect simple.","The instruction focuses on a completed result, so use the simple perfect **have prepared**.","Choose **have prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is perfect continuous, which foregrounds the activity rather than the requested simple form.","B":"This omits been and is not a complete perfect continuous form.","C":"Have as a perfect auxiliary cannot take a to-infinitive.","D":"The instruction focuses on a completed result, so use the simple perfect **have prepared**."}}},{"id":"86f7823b-7bfc-5340-af70-c37843cd7d89","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Use the present perfect continuous: She ____ the old portrait for an hour so far today.","choices":[{"id":"A","text":"has being restoring"},{"id":"B","text":"has been restored"},{"id":"C","text":"has been restoring"},{"id":"D","text":"has restoring"}],"answerId":"C","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **has + been + restoring**. The sentence focuses on the duration of the activity so far today.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"present-perfect-continuous-2","fingerprint":"479b63bb8bc99d71efc951c5c2fdd65eb614d7787da32b1cb8b7ffc624b17706","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **has + been + restoring**. The sentence focuses on the duration of the activity so far today.","Choose **has been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect auxiliary requires been, not being.","B":"A past participle here would suggest passive voice rather than the requested active continuous.","C":"Build **has + been + restoring**. The sentence focuses on the duration of the activity so far today.","D":"Been is missing between the perfect auxiliary and the -ing form."}}},{"id":"34be3daa-474a-56b7-aafc-3a43b6cea43e","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Make a present-perfect-continuous negative: We ____ the old portrait all morning so far today.","choices":[{"id":"A","text":"have been not restoring"},{"id":"B","text":"have not restoring"},{"id":"C","text":"did not been restoring"},{"id":"D","text":"have not been restoring"}],"answerId":"D","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **have**, before **been restoring**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"present-perfect-continuous-2","fingerprint":"6928fc6a21d14b7c758c9aa0b939dc7cf581988404e4a3c91901108725a72924","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **have**, before **been restoring**.","Choose **have not been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary negative position is after the first auxiliary, before been.","B":"Been is missing.","C":"Did cannot combine with been to make a perfect continuous negative.","D":"Put not after **have**, before **been restoring**."}}},{"id":"c0f50841-dfef-56fe-a1ac-4abf18262cd6","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Complete the present-perfect-continuous question: Have they ____ the old portrait for long so far today?","choices":[{"id":"A","text":"being restoring"},{"id":"B","text":"been restore"},{"id":"C","text":"restoring"},{"id":"D","text":"been restoring"}],"answerId":"D","hint":"The first auxiliary has already moved. Supply **been + -ing** after the subject.","explanation":"The first auxiliary is already at the front. After they, keep **been + restoring**.","keywords":["continuous-question"],"skill":"continuous-question","contextKey":"present-perfect-continuous-2","fingerprint":"96efe51c3b56a11a1a510a2527be94f9cbdcf3b7e040c9985b1b2a0e242302d8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary has already moved. Supply **been + -ing** after the subject.","The first auxiliary is already at the front. After they, keep **been + restoring**.","Choose **been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect auxiliary requires been, not being.","B":"The active continuous part requires -ing, not the base form.","C":"The linking auxiliary been is missing.","D":"The first auxiliary is already at the front. After they, keep **been + restoring**."}}},{"id":"90f95214-484e-54d7-a704-83c4857c0e7b","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Choose the present perfect SIMPLE, focusing on completion: I ____ the old portrait so far today.","choices":[{"id":"A","text":"have to restore"},{"id":"B","text":"have restored"},{"id":"C","text":"have been restoring"},{"id":"D","text":"have restoring"}],"answerId":"B","hint":"Separate **completion** from **duration**. The requested form is perfect simple.","explanation":"The instruction focuses on a completed result, so use the simple perfect **have restored**.","keywords":["simple-continuous-contrast"],"skill":"simple-continuous-contrast","contextKey":"present-perfect-continuous-2","fingerprint":"4b3e2161351bed5674ecc60630ee680ebeccd2c436917a1c8a14d704dd2b0a8e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **completion** from **duration**. The requested form is perfect simple.","The instruction focuses on a completed result, so use the simple perfect **have restored**.","Choose **have restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Have as a perfect auxiliary cannot take a to-infinitive.","B":"The instruction focuses on a completed result, so use the simple perfect **have restored**.","C":"This is perfect continuous, which foregrounds the activity rather than the requested simple form.","D":"This omits been and is not a complete perfect continuous form."}}},{"id":"cfd5b3da-cea6-5b9f-a305-122e3c8cbb3c","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Use the present perfect continuous: She ____ the garden fence for an hour so far today.","choices":[{"id":"A","text":"has been measuring"},{"id":"B","text":"has measuring"},{"id":"C","text":"has being measuring"},{"id":"D","text":"has been measured"}],"answerId":"A","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **has + been + measuring**. The sentence focuses on the duration of the activity so far today.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"present-perfect-continuous-3","fingerprint":"c301bd83f209e8ae919489d1469293f365ce07d867bf45e76873919143f773ba","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **has + been + measuring**. The sentence focuses on the duration of the activity so far today.","Choose **has been measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Build **has + been + measuring**. The sentence focuses on the duration of the activity so far today.","B":"Been is missing between the perfect auxiliary and the -ing form.","C":"The perfect auxiliary requires been, not being.","D":"A past participle here would suggest passive voice rather than the requested active continuous."}}},{"id":"fa9e96c6-7cfb-5adc-a279-69c560742f92","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Make a present-perfect-continuous negative: We ____ the garden fence all morning so far today.","choices":[{"id":"A","text":"have been not measuring"},{"id":"B","text":"have not measuring"},{"id":"C","text":"did not been measuring"},{"id":"D","text":"have not been measuring"}],"answerId":"D","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **have**, before **been measuring**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"present-perfect-continuous-3","fingerprint":"c994e9cfbe3be10056e1fae8fee71e8ca4ee92ecd8b8f4dac9a80d65f4ff1553","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **have**, before **been measuring**.","Choose **have not been measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary negative position is after the first auxiliary, before been.","B":"Been is missing.","C":"Did cannot combine with been to make a perfect continuous negative.","D":"Put not after **have**, before **been measuring**."}}},{"id":"0386cab7-2c92-517b-a351-93e35e831d01","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Complete the present-perfect-continuous question: Have they ____ the garden fence for long so far today?","choices":[{"id":"A","text":"been measuring"},{"id":"B","text":"being measuring"},{"id":"C","text":"been measure"},{"id":"D","text":"measuring"}],"answerId":"A","hint":"The first auxiliary has already moved. Supply **been + -ing** after the subject.","explanation":"The first auxiliary is already at the front. After they, keep **been + measuring**.","keywords":["continuous-question"],"skill":"continuous-question","contextKey":"present-perfect-continuous-3","fingerprint":"eb480b170e8d3886f37408836b70a543a2c0629d1c2464b7ceb631ecdf3c7799","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary has already moved. Supply **been + -ing** after the subject.","The first auxiliary is already at the front. After they, keep **been + measuring**.","Choose **been measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The first auxiliary is already at the front. After they, keep **been + measuring**.","B":"The perfect auxiliary requires been, not being.","C":"The active continuous part requires -ing, not the base form.","D":"The linking auxiliary been is missing."}}},{"id":"f157cc7c-b10c-508e-a7c3-ee2463136e37","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Choose the present perfect SIMPLE, focusing on completion: I ____ the garden fence so far today.","choices":[{"id":"A","text":"have been measuring"},{"id":"B","text":"have measuring"},{"id":"C","text":"have to measure"},{"id":"D","text":"have measured"}],"answerId":"D","hint":"Separate **completion** from **duration**. The requested form is perfect simple.","explanation":"The instruction focuses on a completed result, so use the simple perfect **have measured**.","keywords":["simple-continuous-contrast"],"skill":"simple-continuous-contrast","contextKey":"present-perfect-continuous-3","fingerprint":"38e974ec6600336e2c4d53209788e0404bd1019b8856f242c630d98829181fd2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **completion** from **duration**. The requested form is perfect simple.","The instruction focuses on a completed result, so use the simple perfect **have measured**.","Choose **have measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is perfect continuous, which foregrounds the activity rather than the requested simple form.","B":"This omits been and is not a complete perfect continuous form.","C":"Have as a perfect auxiliary cannot take a to-infinitive.","D":"The instruction focuses on a completed result, so use the simple perfect **have measured**."}}},{"id":"7800c9b0-5064-566e-adcf-2d902a5a26c6","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Use the present perfect continuous: She ____ the travel leaflet for an hour so far today.","choices":[{"id":"A","text":"has translating"},{"id":"B","text":"has being translating"},{"id":"C","text":"has been translated"},{"id":"D","text":"has been translating"}],"answerId":"D","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **has + been + translating**. The sentence focuses on the duration of the activity so far today.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"present-perfect-continuous-4","fingerprint":"13b36f341eda0aa3eea51c674064f65a2b78d5d0913c2ff58a4d534699a86758","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **has + been + translating**. The sentence focuses on the duration of the activity so far today.","Choose **has been translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Been is missing between the perfect auxiliary and the -ing form.","B":"The perfect auxiliary requires been, not being.","C":"A past participle here would suggest passive voice rather than the requested active continuous.","D":"Build **has + been + translating**. The sentence focuses on the duration of the activity so far today."}}},{"id":"3c3638d5-1f41-5da3-a516-dd58c6daacf6","topicSlug":"present-perfect-continuous","level":"B2","prompt":"Make a present-perfect-continuous negative: We ____ the travel leaflet all morning so far today.","choices":[{"id":"A","text":"have not been translating"},{"id":"B","text":"have been not translating"},{"id":"C","text":"have not translating"},{"id":"D","text":"did not been translating"}],"answerId":"A","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **have**, before **been translating**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"present-perfect-continuous-4","fingerprint":"461c5e117d4b68342a912846ff3e7bc9cad0254106967fea10961f82018d733d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-perfect-continuous"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **have**, before **been translating**.","Choose **have not been translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Put not after **have**, before **been translating**.","B":"The ordinary nega